  const [taskItems,setTaskItems]=useState<TaskRecord[]>(DEFAULT_TASKS);const [quizList,setQuizList]=useState<QuizSummary[]>([]);const [quizDetail,setQuizDetail]=useState<QuizDetail|null>(null);const [quizAnswers,setQuizAnswers]=useState<Record<string,string>>({});const [quizBusy,setQuizBusy]=useState(false);const [quizLoading,setQuizLoading]=useState(false);
